{"summary": "Inspect border styles in Answer sheet STEP2 and STEP3 areas", "command": "python3 - <<'PY'
import openpyxl
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)
ws=wb['Answer']
from openpyxl.styles.borders import Border

def border_sig(cell):
    b=cell.border
    if b is None:
        return None
    def side(s):
        if s is None:
            return None
        return (s.style, s.color.rgb if s.color else None)
    return (side(b.left), side(b.right), side(b.top), side(b.bottom))

for area_name, (r1,r2,c1,c2) in [('STEP2',(11,13,2,11)), ('STEP3',(20,24,2,11))]:
    print('\n',area_name)
    for r in range(r1,r2+1):
        row=[]
        for c in range(c1,c2+1):
            cell=ws.cell(r,c)
            bs=border_sig(cell)
            # simplify: indicate if any border present
            has= any(side[0] is not None for side in bs) if bs else False
            row.append('1' if has else '0')
        print(r,''.join(row))
PY"}

